// Wisp Atlas: the YASHPEH folktales as stars above the places they were told.
// Tale data is generated by scripts/build-map-data.js into data/map.json;
// data/land.json holds the Natural Earth land outlines (public domain).

(async function () {
  const $ = (sel) => document.querySelector(sel);
  const listEl = $('#list');
  const searchEl = $('#search');
  const bookEl = $('#book');
  const PAGE_SIZE = 150;
  const WORLD = L.latLngBounds([-50, -170], [80, 192]);

  drawSky($('#sky'));

  const [data, land] = await Promise.all([
    fetch('data/map.json').then((r) => r.json()),
    fetch('data/land.json').then((r) => r.json()),
  ]);

  const regions = data.regions;
  const regionById = new Map(regions.map((r) => [r.id, r]));
  const places = data.places.map((p) => ({
    ...p,
    // Keep the far side of the antimeridian next to its neighbours (Chukotka).
    lng: p.lng < -168 ? p.lng + 360 : p.lng,
    stories: p.stories.map(([id, title, bookId, tradition, excerpt]) => ({
      id,
      title: title || 'Untitled',
      bookId,
      tradition,
      excerpt,
      placeId: p.id,
      search: `${title} ${excerpt}`.toLowerCase(),
    })),
  }));
  const placeById = new Map(places.map((p) => [p.id, p]));
  const storyById = new Map(places.flatMap((p) => p.stories.map((s) => [s.id, s])));

  for (const [id, book] of Object.entries(data.books).sort((a, b) => a[1].name.localeCompare(b[1].name))) {
    bookEl.add(new Option(`${book.name} — ${book.author}`, id));
  }

  // ---------- State ----------

  const state = { region: null, place: null, open: null, limit: PAGE_SIZE };
  let matches = new Map(); // place id -> stories matching search + book

  // ---------- Map ----------

  const map = L.map('map', {
    crs: L.CRS.EPSG4326,
    zoomControl: false,
    zoomSnap: 0.1,
    maxZoom: 7,
    maxBounds: WORLD.pad(0.3),
    attributionControl: true,
  });
  map.attributionControl.setPrefix('<a href="https://leafletjs.com">Leaflet</a>');
  map.fitBounds(WORLD);
  const updateMinZoom = () => map.setMinZoom(map.getBoundsZoom(WORLD) - 0.3);
  updateMinZoom();
  window.addEventListener('resize', updateMinZoom);

  // Graticule: faint dotted meridians.
  const grid = [];
  for (let lng = -150; lng <= 180; lng += 30) grid.push([[-58, lng], [84, lng]]);
  L.polyline(grid, { color: '#3A4680', weight: 1, opacity: 0.35, dashArray: '1 6', interactive: false }).addTo(map);

  // Land outlines (Antarctica left out; Chukotka unwrapped past 180°, see scripts/build-land.js).
  L.geoJSON(land, {
    style: { color: '#4A5AA8', weight: 1, dashArray: '2 4', fillColor: '#0E1535', fillOpacity: 1, interactive: false },
    attribution: 'Land: <a href="https://www.naturalearthdata.com">Natural Earth</a>',
  }).addTo(map);

  const brightness = (n) => Math.min(1.9, 0.7 + Math.sqrt(n) / 14);

  const markers = new Map(
    places.map((p, i) => {
      const marker = L.marker([p.lat, p.lng], {
        icon: L.divIcon({
          className: 'star-icon',
          iconSize: [44, 44],
          html: `<span class="star"><span class="ring"></span><span class="ray"></span><span class="ray v"></span><span class="core" style="animation-delay:-${((i * 0.73) % 3.4).toFixed(2)}s"></span><span class="wl"></span></span>`,
        }),
        keyboard: true,
        riseOnHover: true,
      });
      marker.on('click', () => selectPlace(p.id, { pan: false }));
      marker.on('add', () => {
        const el = marker.getElement();
        el.setAttribute('role', 'button');
        el.querySelector('.wl').textContent = p.name;
      });
      return [p.id, marker];
    }),
  );

  // Zoomed in, name the brightest stars; zoomed further, name them all.
  const updateLabels = () => {
    map.getContainer().classList.toggle('labels', map.getZoom() >= 3.5);
    map.getContainer().classList.toggle('labels-all', map.getZoom() >= 5);
  };
  map.on('zoomend', updateLabels);
  $('#zoom-in').addEventListener('click', () => map.zoomIn(0.75));
  $('#zoom-out').addEventListener('click', () => map.zoomOut(0.75));

  // ---------- Filtering ----------

  const inRegion = (p) => !state.region || p.region === state.region;

  function applyFilter() {
    const q = searchEl.value.trim().toLowerCase();
    const book = bookEl.value ? Number(bookEl.value) : null;
    matches = new Map();
    for (const p of places) {
      const hits = p.stories.filter((s) => (!book || s.bookId === book) && (!q || s.search.includes(q)));
      matches.set(p.id, hits);
      const marker = markers.get(p.id);
      if (!hits.length) {
        marker.remove();
        continue;
      }
      if (!map.hasLayer(marker)) marker.addTo(map);
      const el = marker.getElement();
      el.querySelector('.star').style.setProperty('--k', brightness(hits.length));
      el.setAttribute('aria-label', `${p.name}: ${hits.length} ${hits.length === 1 ? 'tale' : 'tales'}`);
      el.classList.toggle('on', p.id === state.place);
      el.classList.toggle('dim', !inRegion(p));
      el.classList.toggle('major', hits.length >= 40);
    }
    render();
  }

  // ---------- Navigation ----------

  function fitPlaces(list, maxZoom = 4) {
    if (!list.length) return;
    const bounds = L.latLngBounds(list.map((p) => [p.lat, p.lng]));
    map.flyToBounds(bounds.pad(0.25), { maxZoom, duration: 0.8 });
  }

  function selectRegion(id) {
    state.region = id;
    state.place = null;
    state.open = null;
    state.limit = PAGE_SIZE;
    if (id) fitPlaces(places.filter((p) => p.region === id));
    else map.flyToBounds(WORLD, { duration: 0.8 });
    syncHash();
    applyFilter();
    listEl.scrollTop = 0;
  }

  function selectPlace(id, { pan = true, open = null } = {}) {
    const p = placeById.get(id);
    state.place = p ? id : null;
    state.open = open;
    state.limit = PAGE_SIZE;
    if (p && !inRegion(p)) state.region = p.region;
    if (p && pan) map.flyTo([p.lat, p.lng], Math.max(map.getZoom(), 3.5), { duration: 0.8 });
    syncHash();
    applyFilter();
    if (open) listEl.querySelector(`[data-story="${open}"]`)?.scrollIntoView({ block: 'center' });
    else listEl.scrollTop = 0;
  }

  function syncHash() {
    const hash = state.place ? state.place + (state.open ? `/${state.open}` : '') : state.region ? `sky:${state.region}` : '';
    history.replaceState(null, '', hash ? `#${hash}` : location.pathname + location.search);
  }

  function followFallingStar() {
    const pool = places.filter(inRegion).flatMap((p) => matches.get(p.id) ?? []);
    if (!pool.length) return;
    const s = pool[Math.floor(Math.random() * pool.length)];
    selectPlace(s.placeId, { open: s.id });
    const p = placeById.get(s.placeId);
    map.once('moveend', () => {
      const pt = map.latLngToContainerPoint([p.lat, p.lng]);
      const box = map.getContainer().getBoundingClientRect();
      const meteor = document.createElement('span');
      meteor.className = 'meteor';
      meteor.style.left = `${box.left + pt.x - 140}px`;
      meteor.style.top = `${box.top + pt.y}px`;
      meteor.style.rotate = '25deg';
      document.body.append(meteor);
      meteor.addEventListener('animationend', () => meteor.remove());
    });
  }

  // ---------- Rendering ----------

  function el(tag, attrs = {}, ...children) {
    const node = document.createElement(tag);
    for (const [k, v] of Object.entries(attrs)) {
      if (k.startsWith('on')) node.addEventListener(k.slice(2), v);
      else node.setAttribute(k, v);
    }
    node.append(...children.filter((c) => c != null));
    return node;
  }

  const tales = (n) => `${n.toLocaleString()} ${n === 1 ? 'tale' : 'tales'}`;

  function render() {
    renderChips();
    renderCrumbs();
    listEl.replaceChildren();

    const place = state.place && placeById.get(state.place);
    const filtering = searchEl.value.trim() || bookEl.value;
    const visible = places.filter((p) => inRegion(p) && matches.get(p.id).length);
    const total = visible.reduce((n, p) => n + matches.get(p.id).length, 0);

    if (place) {
      const stories = matches.get(place.id);
      $('#eyebrow').textContent = place.name;
      $('#count').textContent = tales(stories.length);
      renderTales(stories, false);
      return;
    }

    $('#eyebrow').textContent = state.region ? regionById.get(state.region).name : 'The whole sky';
    $('#count').textContent = tales(total);

    if (filtering) {
      renderTales(visible.flatMap((p) => matches.get(p.id)), true);
      return;
    }
    if (!visible.length) {
      listEl.append(el('p', { class: 'empty' }, 'No stars shine here for this search.'));
      return;
    }
    const ul = el('ul');
    for (const p of [...visible].sort((a, b) => matches.get(b.id).length - matches.get(a.id).length)) {
      const n = matches.get(p.id).length;
      ul.append(
        el(
          'li',
          {},
          el(
            'button',
            {
              class: 'row place-row',
              onclick: () => selectPlace(p.id),
              onmouseenter: () => markers.get(p.id).getElement()?.classList.add('hover'),
              onmouseleave: () => markers.get(p.id).getElement()?.classList.remove('hover'),
            },
            el('span', { class: 't' }, p.name),
            el('span', { class: 'n' }, tales(n)),
          ),
        ),
      );
    }
    listEl.append(ul);
  }

  function renderTales(stories, showPlace) {
    if (!stories.length) {
      listEl.append(el('p', { class: 'empty' }, 'No tales here match this search.'));
      return;
    }
    const ul = el('ul');
    for (const s of stories.slice(0, state.limit)) {
      const book = data.books[s.bookId];
      const p = placeById.get(s.placeId);
      const open = s.id === state.open;
      const meta = showPlace ? `${p.name} · ${book.name}` : `${book.name} · ${book.author}`;
      ul.append(
        el(
          'li',
          { class: `tale${open ? ' open' : ''}`, 'data-story': s.id },
          el(
            'button',
            {
              class: 'row',
              'aria-expanded': String(open),
              onclick: () => {
                state.open = open ? null : s.id;
                syncHash();
                render();
              },
              onmouseenter: () => markers.get(p.id).getElement()?.classList.add('hover'),
              onmouseleave: () => markers.get(p.id).getElement()?.classList.remove('hover'),
            },
            el('span', { class: 't' }, s.title),
            el('span', { class: 'm' }, meta),
          ),
          el(
            'div',
            { class: 'tale-body' },
            s.excerpt ? el('p', {}, s.excerpt) : null,
            el(
              'div',
              { class: 'actions' },
              el('a', { class: 'btn-gold', href: data.storyUrl + s.id, target: '_blank', rel: 'noopener' }, 'Read the tale', arrowIcon()),
              showPlace ? el('button', { class: 'chip', onclick: () => selectPlace(p.id, { open: s.id }) }, 'Show its star') : null,
            ),
          ),
        ),
      );
    }
    listEl.append(ul);
    if (stories.length > state.limit) {
      listEl.append(
        el(
          'button',
          {
            class: 'chip more',
            onclick: () => {
              state.limit += PAGE_SIZE;
              render();
            },
          },
          `Show ${Math.min(PAGE_SIZE, stories.length - state.limit)} more of ${stories.length.toLocaleString()}`,
        ),
      );
    }
  }

  function renderChips() {
    const chips = $('#regions');
    chips.replaceChildren(
      el('button', { class: `chip${state.region ? '' : ' sel'}`, 'aria-pressed': String(!state.region), onclick: () => selectRegion(null) }, 'All tales'),
      ...regions.map((r) => {
        const n = places.filter((p) => p.region === r.id).reduce((sum, p) => sum + matches.get(p.id).length, 0);
        return el(
          'button',
          { class: `chip${state.region === r.id ? ' sel' : ''}`, 'aria-pressed': String(state.region === r.id), onclick: () => selectRegion(r.id) },
          r.name,
          el('span', { class: 'n' }, n.toLocaleString()),
        );
      }),
    );
  }

  function renderCrumbs() {
    const crumbs = $('#crumbs');
    const parts = [];
    const place = state.place && placeById.get(state.place);
    const region = state.region && regionById.get(state.region);
    parts.push(region || place ? el('button', { onclick: () => selectRegion(null) }, 'The whole sky') : el('span', { class: 'here' }, 'The whole sky'));
    if (region) {
      parts.push(el('span', { class: 'sep', 'aria-hidden': 'true' }, '›'));
      parts.push(place ? el('button', { onclick: () => selectRegion(region.id) }, region.name) : el('span', { class: 'here' }, region.name));
    }
    if (place) {
      parts.push(el('span', { class: 'sep', 'aria-hidden': 'true' }, '›'));
      parts.push(el('span', { class: 'here' }, place.name));
    }
    crumbs.replaceChildren(...parts);
  }

  function arrowIcon() {
    const svg = document.createElementNS('http://www.w3.org/2000/svg', 'svg');
    svg.setAttribute('width', '14');
    svg.setAttribute('height', '14');
    svg.setAttribute('viewBox', '0 0 24 24');
    svg.setAttribute('fill', 'none');
    svg.setAttribute('stroke', 'currentColor');
    svg.setAttribute('stroke-width', '2');
    svg.setAttribute('aria-hidden', 'true');
    svg.innerHTML = '<path d="M7 17L17 7M9 7h8v8"></path>';
    return svg;
  }

  // ---------- Events ----------

  let debounce;
  searchEl.addEventListener('input', () => {
    clearTimeout(debounce);
    debounce = setTimeout(() => {
      state.limit = PAGE_SIZE;
      applyFilter();
    }, 150);
  });
  bookEl.addEventListener('change', () => {
    state.limit = PAGE_SIZE;
    applyFilter();
    if (bookEl.value && !state.place) fitPlaces(places.filter((p) => matches.get(p.id).length));
  });
  $('#falling-star').addEventListener('click', followFallingStar);

  // ---------- Start ----------

  const [hashPlace, hashStory] = decodeURIComponent(location.hash.slice(1)).split('/');
  if (hashPlace.startsWith('sky:') && regionById.has(hashPlace.slice(4))) {
    selectRegion(hashPlace.slice(4));
  } else if (placeById.has(hashPlace)) {
    const story = storyById.get(Number(hashStory));
    selectPlace(hashPlace, { open: story && story.placeId === hashPlace ? story.id : null });
  } else {
    applyFilter();
  }
})();

// Scatter faint background stars, seeded so the sky looks the same on every visit.
function drawSky(svg) {
  let seed = 7;
  const rand = () => ((seed = (seed * 16807) % 2147483647) - 1) / 2147483646;
  const w = 1600;
  const h = 1000;
  svg.setAttribute('viewBox', `0 0 ${w} ${h}`);
  svg.setAttribute('preserveAspectRatio', 'xMidYMid slice');
  let dots = '';
  for (let i = 0; i < 260; i++) {
    const r = [0.5, 0.6, 0.8, 1, 1.2][Math.floor(rand() * 5)];
    const o = rand() < 0.3 ? 0.7 : 0.35;
    dots += `<circle cx="${(rand() * w).toFixed(1)}" cy="${(rand() * h).toFixed(1)}" r="${r}" fill="#DDE2FF" opacity="${o}"/>`;
  }
  svg.innerHTML = dots;
}
